import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Declarative Topology Synthesis (DTS)","description":"","frontmatter":{},"headers":[],"relativePath":"research-dts/index.md","filePath":"vendored/research-dts/index.md"}`),a={name:`research-dts/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="declarative-topology-synthesis-dts" tabindex="-1">Declarative Topology Synthesis (DTS) <a class="header-anchor" href="#declarative-topology-synthesis-dts" aria-label="Permalink to “Declarative Topology Synthesis (DTS)”">​</a></h1><p>Programmers of effect handlers know which handler must wrap which — yet they still write the nesting by hand. DTS makes that declaration: you supply a <strong>precedence relation</strong> over handlers, and the compiler synthesizes the nested <code>handle</code> structure at compile time.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>-- given: Auth before Cache before Logging</span></span>
<span class="line"><span>synthesize body [Auth, Cache, Logging]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- synthesizes</span></span>
<span class="line"><span>handle (handle (handle body Auth) Cache) Logging</span></span></code></pre></div><h2 id="what-is-in-this-repo" tabindex="-1">What is in this repo <a class="header-anchor" href="#what-is-in-this-repo" aria-label="Permalink to “What is in this repo”">​</a></h2><table tabindex="0"><thead><tr><th>artifact</th><th>where</th><th>what it is</th></tr></thead><tbody><tr><td>Paper</td><td><a href="https://github.com/handl-lang/research-dts/blob/main/paper/PAPER.md" target="_blank" rel="noreferrer"><code>paper/</code></a></td><td>the write-up (<a href="https://github.com/handl-lang/research-dts/blob/main/paper/paper.pdf" target="_blank" rel="noreferrer">PDF</a>)</td></tr><tr><td>Formalization</td><td><code>lean/</code></td><td>Lean 4: precedence, synthesis, and the topological-sort soundness proof</td></tr><tr><td>Reference implementation</td><td><code>python/</code></td><td>the synthesis pipeline, case studies and property tests</td></tr></tbody></table><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to “Start here”">​</a></h2><ul><li><strong>Reference</strong> — <a href="/docs/research-dts/reference/">Lean modules, Python API, paper targets</a></li><li><strong>How-to</strong> — <a href="/docs/research-dts/how-to/">build the proof, run the pipeline, rebuild the paper</a></li><li><strong>Explanation</strong> — <a href="/docs/research-dts/explanation/">why a static ordering is enough</a></li></ul><h2 id="the-claim-in-one-paragraph" tabindex="-1">The claim in one paragraph <a class="header-anchor" href="#the-claim-in-one-paragraph" aria-label="Permalink to “The claim in one paragraph”">​</a></h2><p>In an arrow-effect language the operations of a handler are <strong>linear and sequential</strong>, so the topology can be decided statically: synthesis is a compile-time transformation, not a runtime dispatch mechanism. The formalization pins down when that transformation is sound — a linear extension of the declared precedence, with deterministic tie-breaking — and the Python implementation exists to keep the formalization honest against concrete programs.</p><p>Decision records and the task log live on the <code>project</code> branch (<code>project/TODO.md</code>).</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};